function cwResultHTML(){const m=cwModel();return `<section class="cw-card cw-result${m.urgency?' cw-urgent':''}" aria-labelledby="cw-next"><span class="cw-tag">${m.urgency===3?'Emergency priority':m.urgency?'Prompt clinical review':cwState().stage==='consult'?'Next step':'Readiness review'}</span><h3 id="cw-next">${esc(m.action)}</h3>${m.why.map(t=>`<p>${esc(t)}</p>`).join('')}${m.missing.length?`<details><summary><b>${m.missing.length} unresolved item${m.missing.length===1?'':'s'}</b></summary><ul class="cw-facts">${m.missing.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}<p class="cw-note">${cwReviewed()?'Reviewed by clinician for the current entered facts.':'Provisional · clinician review of this handoff is still required.'} ${S.draftMode?'Draft mode selected; source-unverified content is not a verified recommendation.':'Source-unverified recommendations require explicit draft selection.'}</p></section>`}
